 85	            const password = prompt("Password Required:");
 86	            rfb.sendCredentials({ password: password });
 87	        }
 88	
 89	        // When this function is called we have received
 90	        // a desktop name from the server
 91	        function updateDesktopName(e) {
 92	            desktopName = e.detail.name;
 93	        }
 94	
 95	        // Since most operating systems will catch Ctrl+Alt+Del
 96	        // before they get a chance to be intercepted by the browser,
 97	        // we provide a way to emulate this key sequence.
 98	        function sendCtrlAltDel() {
 99	            rfb.sendCtrlAltDel();
100	            return false;
101	        }
102	
103	        // Show a status text in the top bar
104	        function status(text) {
105	            document.getElementById('status').textContent = text;
106	        }
107	
108	        // This function extracts the value of one variable from the
109	        // query string. If the variable isn't defined in the URL
110	        // it returns the default value instead.
111	        function readQueryVariable(name, defaultValue) {
112	            // A URL with a query parameter can look like this (But will most probably get logged on the http server):
113	            // https://www.example.com?myqueryparam=myvalue
114	            //
115	            // For privacy (Using a hastag #, the parameters will not be sent to the server)
116	            // the url can be requested in the following way:
117	            // https://www.example.com#myqueryparam=myvalue&password=secreatvalue
118	            //
119	            // Even Mixing public and non public parameters will work:
120	            // https://www.example.com?nonsecretparam=example.com#password=secreatvalue
121	            //
122	            // Note that we use location.href instead of location.search
123	            // because Firefox < 53 has a bug w.r.t location.search
124	            const re = new RegExp('.*[?&]' + name + '=([^&#]*)'),
125	                  match = ''.concat(document.location.href, window.location.hash).match(re);
126	
127	            if (match) {
128	                // We have to decode the URL since want the cleartext value
129	                return decodeURIComponent(match[1]);
130	            }
131	
132	            return defaultValue;
133	        }
